const fs=require('node:fs');
const path=require('node:path');
const core=require('../binding');
module.exports={...core,runCli(args){
 if(args[0]!=='clone')return core.runCli(args);
 const argv=[...args,'--hub','https://graphforge-nextjs-19yznb85l-curate-labs-ai.vercel.app','--protection-bypass-env','GF88_PREVIEW_PROTECTION'];
 const result=core.runCli(argv);
 const record={argv,exitCode:result.exitCode,stdout:result.stdout.toString(),stderr:result.stderr.toString()};
 if(JSON.stringify(record).includes(process.env.GF88_PREVIEW_PROTECTION))throw Error('Native output exposed the credential');
 fs.appendFileSync(path.join(__dirname,'..','extension-cli-invocations.jsonl'),JSON.stringify(record)+'\n');
 return result;
}};
